  // ===== replacements for question types with too few possible variations (wider or multi-parameter versions) =====
  const choose = C; // binomial coefficient (defined with the other utilities above)
  let _H = null; // integer-area (Heronian) triangles with sides up to 60: [a,b,c,area]
  const heron = () => { if (_H) return _H; _H = []; for (let a = 3; a <= 60; a++) for (let b = a; b <= 60; b++) for (let c = b; c < a + b && c <= 60; c++) { const s = a + b + c; if (s % 2) continue; const h = s / 2, A2 = h * (h - a) * (h - b) * (h - c), A = Math.round(Math.sqrt(A2)); if (A > 0 && A * A === A2) _H.push([a, b, c, A]); } return _H; };
  const pickHeron = (r, t) => { const H = heron(); const i = Math.min(H.length - 1, Math.floor((0.15 + 0.7 * t) * H.length + (r.int(0, 100) / 100 - 0.5) * 0.3 * H.length)); return H[Math.max(0, i)]; };

